let state;try{state=E.load(localStorage);}catch(error){app.innerHTML=`<main class="save-error"><h1>Your progress is preserved.</h1><p>${escapeHTML(error.message)}</p><p>Your saved files have not been replaced. Export your saved data and contact the game owner for help fixing this issue.</p><button id="export-recovery" class="button primary">Export saved data</button></main>`;document.querySelector('#export-recovery').addEventListener('click',()=>{const data={};for(const key of [E.SAVE_KEY,E.SAVE_KEY+'-backup',UNIFIED_KEY]){const raw=localStorage.getItem(key);if(raw!==null)data[key]=raw;}const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='copper-empire-support-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});throw error;}
