const online=new OnlineWorkshop(()=>{ownerPanel?.render();if(online.recovering&&(ui.page!=='account'||!document.getElementById('new-password'))){ui.page='account';if(!online.initializing)history.replaceState(null,'','#account');render();return;}if(['account','leaderboards'].includes(ui.page)&&!document.activeElement?.matches('input')&&!ownerPanel?.root.contains(document.activeElement))render();});
