serverAccess=connectServerAccess({online,unified,save,paused:()=>{if(game)setPaused(true);},render,reopen:()=>{if(!online.active){E.background(state);E.checkAchievements(state);save();}resumeSavedAttempt();void pollOnline();},exportLocal:()=>{save();downloadAccessSave(state,'copper-empire-maintenance-backup.json');},exportCloud:async()=>downloadAccessSave(await online.api({command:'save-export'}),'copper-empire-cloud-recovery.json')});
connectAuraForge({state:()=>state,ui,online,applyCloud,render,modal,toast,save,music,canPlay:()=>!serverAccess.blocked,commitLocal:next=>{unified.save(next,true);state=next;state.unifiedRuntime={serverTrade:!!unified.doc.ownerId};}});
function save(){if(online.active)return;try{if(attempt)state.unifiedAttempt=checkpointAttempt(attempt,game);unified.save(state);guestState=state;}catch(error){if(!saveWarning){saveWarning=true;toast('Local save needs attention: '+error.message+' Export your current progress from Account & Cloud.');}}}

let audioProgress=null;
function progressAudio(){const key=online.active?'online-'+online.slot:'local',current={key,level:E.level(state),rebirth:state.rebirth,claims:state.gold.claims.length,ascension:state.ascension.level,achievements:state.achievements.length,deliveries:state.trade.stats.delivered,industrialUnits:state.industry.stats.produced,ready:E.rebirthReady(state),contracts:state.contracts.filter(c=>!c.claimed&&E.contractProgress(state,c)>=c.target).map(c=>c.id)};if(audioProgress?.key===key){if(current.level>audioProgress.level)music.cue('success');if(current.deliveries>audioProgress.deliveries)music.cue('delivery');if(current.industrialUnits>audioProgress.industrialUnits)music.cue('collect');if(current.ascension>audioProgress.ascension||current.achievements>audioProgress.achievements)music.cue('milestone');if(current.rebirth>audioProgress.rebirth||current.claims>audioProgress.claims||current.ready&&!audioProgress.ready)music.cue('milestone');if(current.contracts.some(id=>!audioProgress.contracts.includes(id)))music.cue('contract');}audioProgress=current;}
function sound(type='tap'){music.cue(type,type==='tap'?'interface':'effects');}
function render(){if(serverAccess?.blocked){serverAccess.reconcile();ownerPanel?.render();return;}ui.forgeOnlineActive=online.active;ui.forgeBusy=online.busy||unified.locked;progressAudio();music.setScene(ui.page,state.furnace.jobs);ui.marketClockOffset=state.market.global?(online.clockOffset||0):0;document.documentElement.classList.toggle('reduced-motion',!state.settings.motion);ui.onlineHtml=ui.page==='account'?unifiedAccountView(online,unified,state):ui.page==='leaderboards'?leaderboardView(online):'';app.innerHTML=renderApp(state,ui);fullscreen.sync();if(ui.page==='settings')document.querySelector('.settings-panel')?.insertAdjacentHTML('beforeend',music.controls()+tutorialSettings(state));if(ui.page==='market')document.querySelector('#main-content')?.insertAdjacentHTML('beforeend',globalMarketExtras(online));if(['market','gold'].includes(ui.page)){const m=ui.page==='gold'?state.goldMarket:state.market;document.querySelector('#main-content')?.insertAdjacentHTML('afterbegin',`<div class="market-event-notice">Mode: ${escapeHTML(m.mode||'automatic')} · Regime: ${escapeHTML(m.regime||'quiet')}${m.event?' · Active fictional event: '+escapeHTML(({shortage:'Copper Shortage',demand:'Industrial Demand Surge',manufacturing:'Manufacturing Boom',glut:'Supply Glut',recycling:'Recycling Boom',panic:'Market Panic',recovery:'Market Recovery'})[m.event.id]||m.event.id)+' · until '+new Date(m.event.endsAt).toLocaleTimeString():''}</div>`);}document.querySelector('.topbar-right')?.insertAdjacentHTML('afterbegin',`<button class="quiet-button account-status" data-nav="account">${online.session?'@'+escapeHTML(online.username):'Account & Cloud'}</button>`);if(!online.active)document.querySelector('.topbar-right')?.insertAdjacentHTML('afterbegin',syncStatus(unified));document.title='Copper Empire — Recycling Tycoon';if(online.active&&online.admin?.owner)document.querySelector('#main-content')?.insertAdjacentHTML('afterbegin',`<div class="owner-save-banner">${online.slot==='debug'?'DEBUG WORKSHOP — TEST SAVE':online.classification==='admin_modified'?'MAIN WORKSHOP — ADMIN MODIFIED · EXCLUDED FROM COMPETITION':'MAIN WORKSHOP — LIVE'}</div>`);const mute=$('[data-action="sound"]');if(mute){mute.setAttribute('aria-label',music.preference.muted?'Unmute all audio':'Mute all audio');mute.innerHTML=icon(music.preference.muted?'muted':'sound');}ownerPanel?.render();updateFurnaceInput();}
function page(next){if(!NAV.some(n=>n[0]===next))return;music.cue('navigate','interface');ui.page=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:state.settings.motion?'smooth':'instant'});if(next==='industry')trade.poll();if(['market','gold','leaderboards'].includes(next))pollOnline();}
function modal(html,cls=''){music.cue('open','interface');overlay.innerHTML=`<div class="modal-backdrop"><section class="modal empire-modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1">${html}</section></div>`;document.body.classList.add('modal-open');app.inert=true;requestAnimationFrame(()=>$('.modal',overlay)?.focus());}
function close(){music.cue('cancel','interface');if(attempt&&!online.active){state.unifiedAttempt=null;}attempt=null;game=null;paused=false;held=false;dragging=false;overlay.innerHTML='';document.body.classList.remove('modal-open');app.inert=false;save();render();}
const signatureName=id=>id>=2001&&id<=2030?FACTORY_CHALLENGES[id-2001].name:id>=1001&&id<=1007?GOLD_CLAIMS[id-1001].name+' · Panning':SIGNATURES[id-1].name;
const primary=(action,text,extra='')=>`<button class="button primary full" data-action="${action}" ${extra}>${text}</button>`;
const backButton=()=>'<button class="quiet-button" data-action="close">Back to workshop</button>';
function challengeHeader(){return `<div class="game-header"><span class="game-device">${icon(attempt.mode==='trial'?'refresh':attempt.mode==='boss'?'component':'tools')} ${attempt.mode==='ascension'?'Ascension Trial':attempt.mode==='gold'?GOLD_CLAIMS[attempt.claim].name:attempt.mode==='factory'?'Manufacturing · '+productById(state.industry.jobs.find(j=>j.id===attempt.job)?.product)?.name:attempt.mode==='factory-practice'?'Industrial Practice':attempt.mode==='trial'?'Rebirth '+(state.rebirth+1)+' trial':attempt.mode==='practice'?'Practice · no rewards':attempt.mode==='furnace'?'Optional furnace timing':attempt.mode==='boss'?BOSSES.find(b=>b.id===attempt.boss).name:deviceById(attempt.device).name}</span><button class="icon-button" data-action="${game?'pause':'abandon'}" aria-label="${game?'Pause challenge':'Leave attempt'}">${icon(game?'pause':'close')}</button></div><div class="stage-progress">${attempt.stages.map((id,i)=>`<span class="${i<attempt.index?'done':i===attempt.index?'current':''}" title="${signatureName(id)}">${i<attempt.index?icon('check'):i+1}</span>`).join('<i></i>')}</div>`;}
async function start(id=ui.selected,options={}){if(serverAccess?.blocked)return;if(options.mode==='gold'&&tutorials.first(String(1000+id),()=>start(id,options)))return;if(online.active){const data=await online.command('begin',{device:id,mode:options.mode||'device',difficulty:options.difficulty,boss:options.boss?.id,expert:options.difficulty>=4&&options.mode!=='practice'});applyCloud(data);attempt=data.attempt;briefing();return;}const d=deviceById(id);if((options.mode||'device')==='device'&&id===1&&!state.inventory[1])E.purchaseDevice(state,1);attempt=E.begin(state,id,options);save();briefing();}
function briefing(){game=null;held=false;paused=false;const id=attempt.stages[attempt.index];modal(`${challengeHeader()}<div class="challenge-intro"><div class="challenge-icon">${icon(id===1?'target':id%3===0?'circuit':id%3===1?'component':'brain')}</div><div class="modal-eyebrow">${attempt.mode==='practice'?'PRACTICE':`STAGE ${attempt.index+1} OF ${attempt.stages.length}`}${attempt.mode==='device'&&id===attempt.device?' · SIGNATURE CHALLENGE':''}</div><h2 id="modal-title">${signatureName(id)}</h2><div class="guide-briefing">${guideHelp(MINIGAME_GUIDES[id])}</div><div class="tutorial-briefing-actions"><button class="quiet-button" data-tutorial="replay" data-id="${id}">Watch Tutorial</button></div><div class="briefing-chips"><span class="pill">${['Beginner','Easy','Normal','Hard','Expert','Master','Extreme'][attempt.difficulty]}</span><span class="pill">${attempt.mode==='practice'?'No rewards awarded':id===1&&attempt.difficulty===0?'No starter time limit':'Skill earns the reward'}</span><span class="pill">Keyboard · mouse · touch</span></div>${primary('begin-challenge','Begin challenge '+icon('arrow'))}<button class="quiet-button" data-action="abandon">Leave workbench</button></div>`,'game-modal');}
async function launch(savedGame=null){if(online.active){const data=await online.command('launch');applyCloud(data);attempt=data.attempt;attempt.status='briefing';}recording=[];checkpointRecovery=0;unsavedOutcome=null;if(!attempt||attempt.status!=='briefing')return;const id=attempt.stages[attempt.index];attempt.status='active';if(id<=119&&!state.encountered.includes(id)){state.encountered.push(id);E.checkAchievements(state);save();}game=savedGame||createGame(id,attempt.difficulty,attempt.seed+attempt.index*7919,E.bonuses(state));paused=false;held=false;observedTutorialKey=savedGame?gameGuideKey(game):'';lastFrame=performance.now();const view=gameView(game);modal(`${challengeHeader()}<div class="challenge-live"><div class="live-heading"><div><div class="modal-eyebrow">STAGE ${attempt.index+1} OF ${attempt.stages.length}</div><h2 id="modal-title">${signatureName(id)}</h2></div><span class="game-timer">${icon('timer')}<strong id="time-left">${game.duration?Math.ceil(game.duration)+'s':'No limit'}</strong></span></div><details class="live-help"><summary>Objective & controls</summary><div id="current-guide">${guideHelp(game)}</div><button class="quiet-button" data-tutorial="current">Watch Tutorial</button></details><div class="game-budget" id="game-budget"></div><div id="game-scene">${view.scene}</div><div id="game-controls">${view.controls}</div><div id="game-feedback" role="status" aria-live="polite"></div></div><div id="pause-layer"></div>`,'game-modal wide-game');updateUpgradeButtons();save();music.cue('smeltStart');}
function updateUpgradeButtons(){if(!game||!attempt)return;const b=E.bonuses(state);$$('[data-upgrade-action="hint"]',overlay).forEach(x=>{x.disabled=paused||attempt.hints>=b.hint;x.title=b.hint?'Hints apply once per attempt, not per stage.':'Circuit Analyzer or prestige hint rank required.';});$$('[data-upgrade-action="replay"]',overlay).forEach(x=>{x.disabled=paused||game.phase!=='input'||attempt.replays>=b.replay;x.title=b.replay?'Replays apply once per attempt.':'Memory Assistant or prestige hint rank required.';});}
// Keep live controls mounted while updating the animated scene.
function syncHTML(root,html){const template=document.createElement('template');template.innerHTML=html;function sync(parent,source){for(let i=0;i<source.childNodes.length;i++){const fresh=source.childNodes[i],old=parent.childNodes[i];if(!old){parent.append(fresh.cloneNode(true));continue;}if(old.nodeType!==fresh.nodeType||old.nodeName!==fresh.nodeName){old.replaceWith(fresh.cloneNode(true));continue;}if(fresh.nodeType===3){if(old.nodeValue!==fresh.nodeValue)old.nodeValue=fresh.nodeValue;continue;}if(fresh.nodeType!==1)continue;for(const attribute of [...old.attributes])if(!fresh.hasAttribute(attribute.name))old.removeAttribute(attribute.name);for(const attribute of [...fresh.attributes])if(old.getAttribute(attribute.name)!==attribute.value)old.setAttribute(attribute.name,attribute.value);sync(old,fresh);}while(parent.childNodes.length>source.childNodes.length)parent.lastChild.remove();}sync(root,template.content);}
let lastGuideKey='',observedTutorialKey='';
function teachCurrentPart(){if(!game||tutorials.active)return false;const key=gameGuideKey(game);if(key===observedTutorialKey)return false;observedTutorialKey=key;return tutorials.first(key,()=>{lastFrame=performance.now();paint(true);});}
function paint(controls=false){if(!game||game.status!=='active'||paused||tutorials.active)return;const guideKey=gameGuideKey(game);if(guideKey!==lastGuideKey){const help=$('#current-guide');if(help)help.innerHTML=guideHelp(game);lastGuideKey=guideKey;}const time=$('#time-left');if(time)time.textContent=game.duration?Math.max(0,Math.ceil(game.duration-game.elapsed))+'s':'No limit';const budget=$('#game-budget');if(budget)budget.textContent=game.moves?game.id===53?`${game.moves} phase adjustments · ${game.errors} bad locks`:`${game.moves}/${game.maxMoves} moves · ${game.errors} mistakes`:game.errors?`${game.errors} mistakes`:'';const message=$('#game-feedback');if(message&&message.textContent!==game.message)message.textContent=game.message;if(game.id===33&&held){const t=$('.tracking-target'),m=$('.tracking-marker');if(t)t.style.left=game.target*100+'%';if(m)m.style.left=game.position*100+'%';return;}if((held&&game.id<53&&!document.activeElement?.matches('input[type=range]'))||dragging){const cursor=$('#trace-cursor');if(cursor&&game.cursor){cursor.setAttribute('cx',game.cursor.x);cursor.setAttribute('cy',game.cursor.y);}return;}if(document.activeElement?.id==='titan-code')return;const controlKey=game.id+'-'+(game.phase||'')+'-'+(game.cooldowns?.map(v=>v>0?'1':'0').join('')||'')+'-'+(game.id>=53?JSON.stringify([game.part,game.round,game.locked,game.held]):'');if(controlKey!==lastControlKey){controls=true;lastControlKey=controlKey;}const focus=document.activeElement,wasInScene=!!focus?.closest('#game-scene'),focusInfo=focus?.dataset?.g?{action:focus.dataset.g,...Object.fromEntries(['i','value','board','row','start','command','panel'].map(k=>[k,focus.dataset[k]]))}:null;const v=gameView(game);syncHTML($('#game-scene'),v.scene);if(controls&&!document.activeElement?.matches('#game-controls input[type=range]'))syncHTML($('#game-controls'),v.controls);updateUpgradeButtons();if(focusInfo&&wasInScene){const q=`[data-g="${focusInfo.action}"]`+['i','value','board','row','start','command','panel'].filter(k=>focusInfo[k]!==undefined).map(k=>`[data-${k}="${focusInfo[k]}"]`).join('');$(q,overlay)?.focus({preventScroll:true});}}
function act(action,payload={}){if(serverAccess?.blocked)return;if(!game||paused||tutorials.active||game.status!=='active')return;if(action==='hint'){if(attempt.hints>=E.bonuses(state).hint)return;attempt.hints++;}if(action==='replay'){if(attempt.replays>=E.bonuses(state).replay||game.phase!=='input')return;attempt.replays++;}if(action==='code')payload.code=$('#titan-code')?.value||'';if(action==='trace-key'){const dirs=[[0,-1],[1,0],[0,1],[-1,0]],d=dirs[payload.i];action='trace';payload={x:game.cursor.x+d[0]*5,y:game.cursor.y+d[1]*5};}if(online.active)recording.push(['a',action,structuredClone(payload)]);const before={errors:game.errors};gameAction(game,action,payload);music.feedback(game,action,before);if(!checkOutcome()){if(!['move','trace','pan-pointer'].includes(action))save();paint(true);teachCurrentPart();}}
function checkOutcome(){if(!game||!attempt||game.status==='active')return false;const finished=game;game=null;if(online.active&&!verifiedFailure){verifyOutcome(finished);return true;}held=false;dragging=false;if(finished.status==='failed'){if(!online.active){if(attempt.mode==='factory')I.failProduction(state,attempt);E.stageFail(state,attempt);}save();sound('fail');modal(`<div class="result-screen failure-screen"><div class="result-icon">${icon('tools')}</div><div class="modal-eyebrow">A SETBACK. NOT THE END.</div><h2 id="modal-title">${attempt.mode==='gold'?'Panning failed.':attempt.mode.startsWith('factory')?'Production challenge failed.':'Disassembly failed.'}</h2><p>${escapeHTML(finished.reason)}</p><div class="failed-rewards"><span>${icon('copper')} 0 mg ${attempt.mode==='gold'?'gold':'copper'}</span><span>${icon('bolt')} 0 XP</span></div><div class="notice">${icon('box')} ${attempt.mode==='device'?'Your original electronic is safe in inventory. All stage progress has reset.':attempt.mode==='trial'?'The trial consumed no money, copper, or electronics.':attempt.mode==='factory'?'Your funded batch is safe. Retry its primary challenge without paying inputs or fees again. Each failure adds 10s processing, capped at 120s.':attempt.mode==='furnace'?'The optional bonus was not earned. Your original batch is still processing.':'This attempt grants no rewards. A2 stage retries preserve completed stages while available; restarting the full trial resets every stage.'}</div>${attempt.status==='retry'?primary('retry-trial-stage','Repeat this trial stage · '+(3-attempt.retriesUsed)+' later retries remain'):''}${attempt.mode!=='furnace'?primary('retry',attempt.status==='retry'?'Restart full trial':'Try again '+icon('refresh')):''}${backButton()}</div>`,'result-modal');return true;}
 const report=stageReport(finished);E.stagePass(attempt,report.score,report);save();sound('success');
 if(attempt.status==='complete')complete();else modal(`${challengeHeader()}<div class="challenge-intro"><div class="challenge-icon success-icon">${icon('check')}</div><div class="modal-eyebrow">NICE WORK. KEEP IT GOING.</div><h2 id="modal-title">One step closer.</h2><p>Stage ${attempt.index} complete. Every remaining stage must be completed before the recovery earns a reward.</p><div class="next-challenge"><span>UP NEXT</span><strong>${signatureName(attempt.stages[attempt.index])}</strong></div>${primary('next-stage','Continue to stage '+(attempt.index+1)+' '+icon('arrow'))}</div>`,'game-modal');return true;
}
function complete(serverResult=null){if(attempt.mode==='factory'){const result=serverResult||I.finishProductionChallenge(state,attempt,E.performanceGrade(attempt.scores));save();render();modal(`<div class="result-screen"><h2 id="modal-title">Production approved.</h2><p>Grade ${result.grade}. The funded batch is now processing. Collect the products when its timer finishes; this is when manual mastery is recorded.</p><button class="button primary" data-action="close">Back to production</button></div>`,'result-modal');return;}if(attempt.mode==='factory-practice'&&!online.active){attempt.paid=true;if(attempt.stages[0]>=2026&&!state.industry.optional.includes(attempt.stages[0]))state.industry.optional.push(attempt.stages[0]);serverResult={practice:true,grade:E.performanceGrade(attempt.scores),amount:0n,xp:0};}if(attempt.mode==='furnace'){const job=state.furnace.jobs.find(j=>j.id===attempt.job);let secondsSaved=serverResult?.secondsSaved||0;if(!online.active&&!attempt.paid){secondsSaved=E.furnaceBonus(state,job)/1000;attempt.paid=true;save();}modal(`<div class="result-screen"><div class="challenge-icon success-icon">${icon('bolt')}</div><h2 id="modal-title">${secondsSaved?'A little more efficient.':'Your batch is ready.'}</h2><p>${secondsSaved?secondsSaved.toFixed(2)+' seconds removed from the remaining virtual processing time.':'The batch finished while you completed the challenge, so no additional time needed to be removed.'} No copper or XP awarded.</p>${primary('close','Back to smelting')}</div>`,'result-modal');return;}
 const result=serverResult||E.reward(state,attempt);music.cue(result.boss?'milestone':'reward');save();render();if(result.trial)return rebirthConfirm();if(result.ascension)return ascensionConfirm();if(result.gold){modal(`<div class="result-screen success-screen"><div class="modal-eyebrow">THREE ROUNDS. EVERY MILLIGRAM EARNED.</div><h2 id="modal-title">A golden recovery.</h2><div class="pan-gold reward-gold">✦ ✧ ✦</div><p>${GOLD_CLAIMS[result.claim].name} · Grade ${result.grade}</p><div class="reward-total">+${result.amount.toLocaleString()} mg gold</div><p>Your gold and recovered-gold milestone total are saved. This pan pays only once.</p>${primary('retry','Pan this claim again')}${backButton()}</div>`,'result-modal');return;}if(result.practice){modal(`<div class="result-screen"><div class="challenge-icon success-icon">${icon('target')}</div><div class="modal-eyebrow">PRACTICE MAKES POSSIBILITY.</div><h2 id="modal-title">A little sharper.</h2><p>Grade ${result.grade}. Practice awards no money, copper, XP, or items.</p>${primary('retry','Practice again')}${backButton()}</div>`,'result-modal');return;}
 modal(`<div class="result-screen success-screen"><div class="modal-eyebrow">ANOTHER SECOND LIFE, MADE POSSIBLE.</div><h2 id="modal-title">That’s the good stuff.</h2><p>${result.boss?'Boss machine recovered.':deviceById(attempt.device).name+' successfully recovered.'}</p><div class="reveal-art"><div class="reveal-device">${illustration(deviceById(attempt.device),'reveal')}</div><div class="reveal-copper">${coilArt()}</div><span class="result-grade">${result.grade}<small>${{EX:'EXCEPTIONAL',S:'SUPERB',A:'EXCELLENT',B:'GOOD',C:'COMPLETED'}[result.grade]}</small></span></div><div class="reward-total">+${result.boss?money(result.money,true):copper(result.amount)}</div>${result.performance?gradingResults(result.performance):''}${result.boss?'':`<div class="reward-breakdown">Exact total: ${result.amount.toLocaleString()} mg<br>Base ${copper(result.base)} · grade +${copper(result.gradeBonus)} · tools +${copper(result.toolBonus)}</div>`}<div class="success-rewards"><span>${icon('bolt')} +${result.xp} XP</span>${result.part?`<span>${icon('component')} +1 recovered part</span>`:''}${result.rarePart?`<span class="rare-reward">${icon('spark')} Rare copper core</span>`:''}${result.special?`<span class="rare-reward">${icon('spark')} ${copper(result.special)} special-quality copper</span>`:`<span>${icon('leaf')} A little less landfill</span>`}</div>${primary('close','Back to the workbench '+icon('arrow'))}<small class="stylized-note">Your exact rewards are already saved. This recovery can only pay once.</small></div>`,'result-modal');}
function ascensionConfirm(){const r=E.ascensionRequirement(state);modal(`<div class="result-screen"><div class="modal-eyebrow">TRIAL COMPLETE · SEPARATE RESET CONFIRMATION</div><h2 id="modal-title">Ascend to A${r.next}?</h2><p>Resets Rebirth to R0, level/XP, ordinary money and copper, electronics, tools, ordinary prestige points and ranks, crafted materials, temporary research, contracts, processing jobs and ordinary facilities (furnace, automation and refining). Stage Compression resets to rank 0; rank 1 costs 100 g.</p><p>Keeps achievements, lifetime statistics and history, auras, cosmetics, Ascension level, CE and upgrades, all encountered Practice signatures, gold inventory, claims, equipment and Golden Engineering, and permanent industry facilities, funded production, warehouse goods, workers, licenses, relationships and ships. Dispatched shipments retain their locked payouts.</p><div class="notice">The reset happens only when you press Confirm Ascension.</div>${primary('confirm-ascension','Confirm Ascension '+r.next)}<button class="quiet-button" data-action="close">Keep this run</button></div>`,'result-modal');}
function rebirthConfirm(){const r=E.rebirthRequirement(state);modal(`<div class="result-screen"><div class="challenge-icon success-icon">${icon('refresh')}</div><div class="modal-eyebrow">TRIAL COMPLETE. YOUR CHOICE.</div><h2 id="modal-title">Begin chapter ${r.next}?</h2><p>Your wallet, raw copper, current XP, ordinary tools and inventory will reset. Your auras, prestige, achievements, facilities, and lifetime progress stay with you.</p><div class="notice">${icon('star')} Earn ${r.next} PP.${r.next<=12?' Unlock exactly four new electronics.':' Continue repeatable prestige progression.'} The starter motor remains free.</div>${primary('confirm-rebirth','Confirm rebirth '+r.next)}<button class="quiet-button" data-action="close">Keep working in this run</button></div>`,'result-modal');}
function setPaused(value){if(!game||game.status!=='active')return;paused=value;lastFrame=performance.now();held=false;dragging=false;$('.challenge-live').inert=value;$('.game-header').inert=value;const layer=$('#pause-layer');layer.classList.toggle('visible',value);layer.innerHTML=value?`<div class="pause-content">${icon('pause')}<h3>Take a breather.</h3><p>Your challenge is paused. Resume when you’re ready.</p>${checkpointRecovery?'<button class="button primary" data-online="retry-clock">Retry cloud checkpoint</button><button class="button secondary" data-online="refresh-stage">Refresh workshop</button>':primary('resume','Resume challenge '+icon('play'))}<button class="quiet-button" data-action="abandon">Leave workbench</button></div>`:'';save();if(value)$('[data-action="resume"]')?.focus();}
async function action(name,el){try{if(serverAccess?.blocked&&name!=='export')throw Error('The workshop is temporarily closed. Your progress is saved.');if(verifying)throw Error('Your challenge is being verified. Please wait.');if((unified.locked||ui.forgePending)&&!['export','close','pause'].includes(name))throw Error('A transaction is processing. Please wait.');if(!online.active&&unified.connected&&['sell','sell-custom','gold-buy','gold-sell','sell-ingots','sell-refined'].includes(name)){await unifiedAction(name,el);return;}if(name.startsWith('trade-')){await trade.action(name,el);music.action(name);return;}if(name.startsWith('industry-')){if(name==='industry-reserve-confirm'&&!ui.industryPending?.auto){const product=productById(ui.industryPending?.product);if(product&&tutorials.first(String(product.game),()=>action(name,el)))return;}await industry.action(name,el);music.action(name);if(ui.page==='industry')trade.poll();return;}if(name==='sound'){music.set('muted',!music.preference.muted);render();return;}if(name==='furnace-quick'){const f=E.furnaceSettings(state),available=state.copper[0]/1000000n,max=available<f.wholeKg?available:f.wholeKg;const choice=el.dataset.id;$('#furnace-amount').value=String(choice==='max'?max:choice==='1'?1n:f.wholeKg*BigInt(choice)/100n||1n);updateFurnaceInput();return;}if(online.active&&await cloudAction(name,el))return;let message='';const id=el?.dataset.id;switch(name){
 case 'select':ui.selected=Number(id);page('workshop');return;
 case 'open-workshop':page('workshop');return;
 case 'purchase':{const d=E.purchaseDevice(state,Number(id));message=d.name+' added to inventory.';break;}
 case 'start':await start();return;
 case 'start-expert':if(state.rebirth<4)throw Error('Expert recovery unlocks at Rebirth 4.');await start(ui.selected,{difficulty:Math.max(4,deviceById(ui.selected).difficulty)});return;
 case 'practice':await start(Number(id),{mode:'practice',difficulty:ui.practiceDifficulty});return;
 case 'begin-challenge':{const key=String(attempt.stages[attempt.index]);if(!tutorials.first(key,()=>launch()))await launch();return;}
 case 'next-stage':briefing();return;
 case 'pause':setPaused(true);return;
 case 'resume':setPaused(false);return;
 case 'close':if(game){setPaused(true);return;}close();return;
 case 'inspect-model':{const d=deviceById(ui.selected);modal(`<div class="result-screen"><div class="modal-eyebrow">PHYSICAL MODEL · CE—${String(d.id).padStart(3,'0')}</div><h2 id="modal-title">${d.name}</h2><div class="enlarged-industrial-model">${illustration(d,'inspection')}</div><p>Fictional salvage equipment. The visible housings, copper windings, supports and cooling machinery belong to this device’s individual model.</p>${backButton()}</div>`,'model-modal');return;}
 case 'abandon':if(attempt){if(!game){attempt.status='active';game={status:'failed',reason:'You left before every required challenge was complete.'};}else{game.status='failed';game.reason='You left before every required challenge was complete.';}checkOutcome();}return;
 case 'retry-trial-stage':{if(online.active){const data=await online.command('retry-trial-stage');applyCloud(data);attempt=data.attempt;}else E.retryAscensionStage(state,attempt);save();briefing();return;}
 case 'retry':{if(attempt?.mode==='factory'){await industry.action('industry-begin',{dataset:{id:attempt.job}});return;}if(attempt?.mode==='factory-practice'){await industry.action('industry-practice',{dataset:{id:attempt.stages[0]}});return;}const old=attempt;if(!old)return;if(old.mode==='boss')await start(old.device,{mode:'boss',boss:BOSSES.find(b=>b.id===old.boss)});else await start(old.device,{mode:old.mode,difficulty:old.difficulty});return;}
 case 'compression':E.buyCompression(state,Number(el.dataset.rank));message='Stage Compression purchased; retained through Rebirth and reset by Ascension.';break;
 case 'review-essence-refund':modal(`<div class="result-screen"><h2 id="modal-title">Reassign your Copper Essence?</h2><p>Refund the exact CE spent on skill ranks and clear those ranks. Your Ascension level, automatic recovery bonus, gold, completed research and all other progress stay saved. You can buy a different combination immediately.</p>${primary('refund-essence','Confirm skill refund')}<button class="quiet-button" data-action="close">Keep current skills</button></div>`,'result-modal');return;
 case 'refund-essence':E.refundEssence(state);save();close();page('ascension');toast('Skill costs refunded exactly. Choose your new ranks.');return;
 case 'essence':E.buyEssence(state,id,Number(el.dataset.rank));message='Permanent Ascension upgrade purchased.';break;
 case 'gold-equipment':E.buyGoldEquipment(state,id,Number(el.dataset.rank));message='Gold equipment upgraded.';break;
 case 'gold-research':E.buyGoldResearch(state,id);message='Golden Engineering research complete.';break;
 case 'gold-claim':E.unlockGoldClaim(state,Number(id));message='River claim unlocked permanently.';break;
 case 'gold-buy':case 'gold-sell':{const amount=parseCopper($('#gold-trade-amount').value,'mg');const trade=E.tradeGold(state,name==='gold-buy'?'buy':'sell',amount,state.goldMarket.quote);message=trade.proceeds?'Gold sold for '+money(trade.proceeds):'Gold purchased. Purchased gold does not count toward recovery milestones.';break;}
 case 'gold-pan':await start(Number(id)+1,{mode:'gold',difficulty:6});return;
 case 'ascension-trial':await start(1,{mode:'ascension',difficulty:6});return;
 case 'review-ascension':ascensionConfirm();return;
 case 'confirm-ascension':E.confirmAscension(state);save();close();page('ascension');toast('Ascension complete. Your permanent rewards are saved.');return;
 case 'tool':E.buyTool(state,id);message='Tool equipped. Its bonus is active in your next attempt.';break;
 case 'market-upgrade':E.buyMarket(state,id);message='Market upgrade purchased.';break;
 case 'sell':{const amount=state.copper[ui.quality]*BigInt(el.dataset.percent)/100n;message='Sold for '+money(E.sell(state,amount,ui.quality))+'.';break;}
 case 'sell-custom':message='Sold for '+money(E.sell(state,parseCopper($('#sell-amount').value,$('#sell-unit').value),ui.quality))+'.';break;
 case 'market-refresh':E.refreshMarket(state);message='A new quote has been simulated.';break;
 case 'set-alert':{const quote=Math.round(Number($('#price-alert').value)*10000);if(!Number.isFinite(quote)||quote<(state.market.minimum||3000)||quote>(state.market.maximum||20000))throw Error('Choose an alert quote within the current market bounds.');state.market.alert=quote;message='Price alert saved.';break;}
 case 'limit-order':{const amount=parseCopper($('#sell-amount').value,$('#sell-unit').value),quote=Math.round(Number($('#limit-price').value)*10000);if(!state.market.upgrades.includes('terminal')||amount<=0n||amount>state.copper[ui.quality]||!Number.isFinite(quote)||quote<(state.market.minimum||3000)||quote>(state.market.maximum||20000))throw Error('Enter an available custom amount and a quote within the current market bounds.');state.market.limit={amount,quote,quality:ui.quality};message='Limit sale order saved.';break;}
 case 'cancel-order':state.market.limit=null;message='Limit order cancelled.';break;
 case 'craft':E.craft(state,id);message='Component crafted. Materials deducted.';break;
 case 'research':E.research(state,id);message='Workshop research completed.';break;
 case 'roll':throw Error('Open Aura Forge to review and purchase a batch.');
 case 'equip-aura':E.equipAura(state,id);message='Aura equipped. Only this aura supplies its bonus.';break;
 case 'equip-and-close':E.equipAura(state,id);save();close();return;
 case 'trial':await start(1,{mode:'trial',difficulty:Math.min(6,Math.floor(state.rebirth/2))});return;
 case 'review-rebirth':rebirthConfirm();return;
 case 'confirm-rebirth':{const next=E.confirmRebirth(state);save();close();ui.category=String(Math.min(18,next));page('rebirth');toast('Rebirth '+next+' complete. '+next+' Prestige Points earned.');sound('success');return;}
 case 'prestige':E.buyPrestige(state,id);message='Permanent prestige rank purchased.';break;
 case 'furnace-queue':E.queueFurnace(state,parseCopper($('#furnace-amount').value,'kg'));message='Finite batch queued. Copper is deducted when it starts.';break;
 case 'furnace-cancel':E.cancelFurnaceQueue(state,id);message='Queued batch cancelled.';break;
 case 'furnace-start':{const amount=parseCopper($('#furnace-amount').value,'kg');E.startFurnace(state,amount);message='Virtual batch started. Copper deducted.';break;}
 case 'furnace-collect':message=E.collectFurnace(state,id)+' ingots collected.';break;
 case 'furnace-upgrade':E.buyFurnaceUpgrade(state,id);message='Furnace improvement purchased.';break;
 case 'sell-ingots':message='Ingots sold for '+money(E.sellIngots(state))+'.';break;
 case 'furnace-challenge':{const job=state.furnace.jobs.find(j=>j.id===id);if(!job||job.bonusUsed||Date.now()>=job.ends)throw Error('This optional batch challenge is unavailable.');job.bonusUsed=true;attempt={id:'furnace-'+id,mode:'furnace',job:id,device:1,stages:[1],index:0,scores:[],status:'briefing',seed:seedNow(),difficulty:1,hints:0,replays:0,paid:false};save();briefing();return;}
 case 'buy-automation':E.buyAutomation(state);message='Automated workshop built.';break;
 case 'auto-toggle':if(!state.automation.purchased||!['stock','wire'].includes(id))throw Error('Build the automation facility first.');state.automation[id]=!state.automation[id];break;
 case 'buy-refining':E.buyRefining(state);message='Industrial refining facility built.';break;
 case 'refine':message=E.refine(state)+' refined ingot(s) produced with exact input accounting.';break;
 case 'sell-refined':message='Refined ingots sold for '+money(E.sellIngots(state,true))+'.';break;
 case 'refining-research':E.refineResearch(state);message='Refining research improved.';break;
 case 'accept-contract':E.acceptContract(state,E.availableContracts(state).find(c=>c.id===id));message='Contract accepted.';break;
 case 'claim-contract':E.claimContract(state,id);message='Contract rewards claimed.';break;
 case 'boss':{const boss=BOSSES.find(b=>b.id===id);await start(Math.min(52,boss.rebirth*4+1),{mode:'boss',boss,difficulty:boss.difficulty});return;}
 case 'setting':if(['sound','motion'].includes(id))state.settings[id]=!state.settings[id];break;
 case 'sound':state.settings.sound=!state.settings.sound;break;
 case 'dismiss-migration':ui.migrationDismissed=true;render();return;
 case 'export':{const blob=new Blob([E.encode(state)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='copper-empire-r'+state.rebirth+'-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your save has been exported.');return;}

 default:return;
 }E.checkAchievements(state);save();render();music.action(name);if(name==='furnace-collect')audioIngots=state.stats.ingots;if(message)toast(message);
 }catch(error){music.cue('incorrect');toast(error.message||'The action could not be completed.');}}
app.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav)return page(nav.dataset.nav);const el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el);});
overlay.addEventListener('click',e=>{const drop=e.target.closest('[data-drop]');if(drop&&touchDrop&&performance.now()<touchDrop.until&&drop.dataset.drop===touchDrop.action&&drop.dataset.i===touchDrop.i&&drop.dataset.start===touchDrop.start){e.preventDefault();return;}const rhythmButton=e.target.closest('[data-rhythm-lane]');if(rhythmButton){if(e.detail===0&&game)act(game.held[Number(rhythmButton.dataset.rhythmLane)]?'release':'beat',{i:Number(rhythmButton.dataset.rhythmLane)});return;}const el=e.target.closest('[data-action]');if(el)return action(el.dataset.action,el);const g=e.target.closest('[data-g]');if(g&&!g.disabled&&!['slider','offset'].includes(g.dataset.g))act(g.dataset.g,payload(g));});
function payload(el){return Object.fromEntries(Object.entries(el.dataset).filter(([k])=>!['g','drag','drop','upgradeAction'].includes(k)).map(([k,v])=>[k,['i','value','row','start','board'].includes(k)?Number(v):v]));}
overlay.addEventListener('input',e=>{if(e.target.matches('[data-g="slider"],[data-g="offset"]')){e.target.closest('label').querySelector('output').textContent=e.target.value+(e.target.dataset.g==='offset'?'°':'');act(e.target.dataset.g,{...payload(e.target),value:Number(e.target.value)});}});
app.addEventListener('change',async e=>{const el=e.target;if(industry.field(el)||trade.field(el))return;if(el.matches('[data-audio-mode]')){music.set('mode',el.value);return;}if(el.matches('[data-audio-track]')){const changing=music.selectTrack(el.value);render();await changing;render();return;}switch(el.id){case 'shop-category':ui.category=el.value;render();break;case 'shop-sort':ui.sort=el.value;render();break;case 'owned-filter':ui.shopFilter=el.checked?'owned':'all';render();break;case 'practice-difficulty':ui.practiceDifficulty=Number(el.value);break;case 'sale-quality':ui.quality=Number(el.value);render();break;}});
app.addEventListener('input',e=>{if(e.target.id==='shop-search'){const position=e.target.selectionStart;ui.search=e.target.value;render();const input=$('#shop-search');input.focus();input.setSelectionRange(position,position);}});
function tracePoint(e){const svg=$('#trace-board');if(!svg||!game)return;const rect=svg.getBoundingClientRect();act('trace',{x:(e.clientX-rect.left)/rect.width*600,y:(e.clientY-rect.top)/rect.height*240});}
function panPoint(e){const track=$('[data-pan-track]');if(!track)return;const rect=track.getBoundingClientRect();act('pan-pointer',{position:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width))});}
function trackingPoint(e){const track=$('[data-tracking]');if(!track||!game)return;const rect=track.getBoundingClientRect();act('move',{position:Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width))});}
let touchDrag=null,touchDrop=null;const rhythmPointers=new Map();
overlay.addEventListener('pointerdown',e=>{if(!game||paused)return;held=true;const lane=e.target.closest('[data-rhythm-lane]');if(lane){const i=Number(lane.dataset.rhythmLane);if(e.pointerType==='mouse'&&game.held[i])act('release',{i});else act('beat',{i});if(e.pointerType!=='mouse')rhythmPointers.set(e.pointerId,i);e.preventDefault();}if(e.target.closest('[data-pan-track]'))panPoint(e);const trace=e.target.closest('#trace-board');if(trace){traceActive=true;trace.setPointerCapture?.(e.pointerId);tracePoint(e);e.preventDefault();}if(e.target.closest('[data-tracking]')){trackingPoint(e);e.preventDefault();}const piece=e.target.closest('[data-drag]');if(piece&&e.pointerType!=='mouse'){e.preventDefault();touchDrag={x:e.clientX,y:e.clientY,i:Number(piece.dataset.drag)};act('select',{i:touchDrag.i});}});
overlay.addEventListener('pointermove',e=>{if(!game||paused)return;if(held&&e.target.closest('[data-pan-track]'))panPoint(e);if(traceActive){for(const p of [...(e.getCoalescedEvents?.()||[]),e])tracePoint(p);e.preventDefault();}if(held&&e.target.closest('[data-tracking]'))trackingPoint(e);});
window.addEventListener('pointerup',e=>{if(game&&[69,77].includes(game.id)&&!paused&&rhythmPointers.has(e.pointerId)){act('release',{i:rhythmPointers.get(e.pointerId)});rhythmPointers.delete(e.pointerId);}if(touchDrag&&Math.hypot(e.clientX-touchDrag.x,e.clientY-touchDrag.y)>8){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');if(target){touchDrop={action:target.dataset.drop,i:target.dataset.i,start:target.dataset.start,until:performance.now()+400};act(target.dataset.drop,payload(target));}}touchDrag=null;traceActive=false;held=false;if(attempt)save();});
window.addEventListener('pointercancel',e=>{if(rhythmPointers.has(e.pointerId)){act('release',{i:rhythmPointers.get(e.pointerId)});rhythmPointers.delete(e.pointerId);}held=false;traceActive=false;touchDrag=null;});
overlay.addEventListener('dragstart',e=>{const piece=e.target.closest('[data-drag]');if(!piece||paused||!game){e.preventDefault();return;}dragging=true;act('select',{i:Number(piece.dataset.drag)});e.dataTransfer.setData('text/plain',piece.dataset.drag);e.dataTransfer.effectAllowed='move';});
overlay.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault();});
overlay.addEventListener('drop',e=>{e.preventDefault();const target=e.target.closest('[data-drop]');if(target&&dragging)act(target.dataset.drop,payload(target));dragging=false;held=false;paint(true);});
overlay.addEventListener('dragend',()=>{dragging=false;held=false;});
document.addEventListener('keydown',e=>{if(!overlay.firstElementChild)return;if(e.key==='Tab'){const items=$$('button:not([disabled]),input,select,summary,[tabindex="0"]',overlay).filter(el=>el.getClientRects().length&&!el.closest('[inert]'));const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Escape'){e.preventDefault();if(game)setPaused(!paused);else if(attempt){action('abandon');}else close();return;}if(game?.id===5&&e.target.closest('[data-g="pulse"]')&&['Enter',' '].includes(e.key)){e.preventDefault();if(!paused&&!e.repeat)act('pulse',{value:Number(e.target.closest('[data-g="pulse"]').dataset.value)});return;}if(!game||paused||(e.repeat&&![12,19,26,33,39].includes(game.id))||e.target.matches('input,select')||e.target.closest('[data-action]'))return;const id=game.id,key=e.key.toLowerCase();if(id>=1001&&id<=1007&&['arrowleft','arrowright',' '].includes(key)){e.preventDefault();act(key===' '?'shake':'nudge',{value:key==='arrowleft'?-1:1});return;}if([60,69,77].includes(id)&&/^[1-6]$/.test(key)){e.preventDefault();act('beat',{i:Number(key)-1});return;}if(id===53&&e.code==='Space'){e.preventDefault();act('lock');return;}if(id===5&&['s','l'].includes(key)){e.preventDefault();act('pulse',{value:key==='l'?1:0});return;}if([1,16,52].includes(id)&&e.code==='Space'){e.preventDefault();act(id===1?'hit':id===16?'beat':'convert',{i:0});return;}if(id===37&&['a','d','arrowleft','arrowright'].includes(key)){e.preventDefault();act('beat',{i:['a','arrowleft'].includes(key)?0:1});return;}if(id===12&&key.startsWith('arrow')){e.preventDefault();act('trace-key',{i:{arrowup:0,arrowright:1,arrowdown:2,arrowleft:3}[key]});return;}if([19,26,33,39].includes(id)&&['arrowleft','arrowright','arrowup','arrowdown'].includes(key)){e.preventDefault();const positive=['arrowright','arrowup'].includes(key);act(id===19?'push':id===26?(positive?'up':'down'):id===33?'move':'impulse',{value:positive?1:-1});return;}if(/^[1-9]$/.test(key)){const i=Number(key)-1;if(id===20||id===46){e.preventDefault();act('symbol',{i});}else if([2,11,17,28,40,50].includes(id)){const piece=$(`[data-drag="${i}"]`);if(piece){e.preventDefault();act('select',{i});}}}});
