function frame(now){tutorials.tick(now);if(game&&!paused&&!tutorials.active)teachCurrentPart();const dt=Math.min(.04,Math.max(0,(now-(lastFrame||now))/1000));lastFrame=now;if(!serverAccess?.blocked&&game&&!paused&&!tutorials.active&&!document.hidden){if(online.active&&dt>0)recording.push(['t',dt]);tickGame(game,dt);music.observe(game);if(online.active&&game.id===1&&!game.duration&&recording.length>12000&&!checkpointPending){const events=recording.splice(0);checkpointPending=online.command('checkpoint',{attempt:attempt.id,index:attempt.index,events}).then(data=>{applyCloud(data);attempt=data.attempt;}).catch(error=>{checkpointRecovery=events.length;recording.unshift(...events);if(game)setPaused(true);toast(error.message+' Resume after reconnecting.');throw error;}).finally(()=>{checkpointPending=null;});checkpointPending.catch(()=>{});}if(!checkOutcome()&&now-lastPaint>65){paint();lastPaint=now;}}requestAnimationFrame(frame);}
function updateFurnaceInput(){const input=$('#furnace-amount');if(!input)return;const f=E.furnaceSettings(state);let kg=0n;try{if(/^\d+$/.test(input.value))kg=BigInt(input.value);}catch{}const valid=kg>=1n&&kg<=f.wholeKg,enough=kg*1000000n<=state.copper[0],free=state.furnace.jobs.length<f.slots;const reason=!valid?'Choose a whole kg from 1 to '+f.wholeKg+'.':!enough?'Not enough standard copper.':!free?'All slots occupied. Collect a ready batch or queue the next one.':'';const start=$('[data-action="furnace-start"]'),queue=$('[data-action="furnace-queue"]');if(start){start.disabled=!!reason;start.title=reason;}if(queue)queue.disabled=!valid||!f.queueLimit||state.furnace.queue.length>=f.queueLimit;const preview=$('#furnace-preview');if(preview)preview.textContent=reason||(kg+' kg → '+kg+' ingots · '+f.duration.toFixed(2)+'s · '+(f.sale/100).toFixed(2)+'× sale value.');}
let furnaceAudioKey='',audioJobs=new Map(),audioIngots=0;
function furnaceAudio(now){const key=(online.active?'online-'+online.slot:'local');if(key!==furnaceAudioKey){furnaceAudioKey=key;audioJobs=new Map(state.furnace.jobs.filter(j=>j.ends>now).map(j=>[j.id,j.ends]));audioIngots=state.stats.ingots;return;}let ready=false,started=false;for(const job of state.furnace.jobs)if(!audioJobs.has(job.id)&&job.ends>now)started=true;if(started)music.cue('smeltStart');for(const job of state.furnace.jobs)if(job.ends<=now&&audioJobs.has(job.id))ready=true;if(ready)music.cue('ready');if(state.stats.ingots>audioIngots)music.cue('collect');audioIngots=state.stats.ingots;audioJobs=new Map(state.furnace.jobs.filter(j=>j.ends>now).map(j=>[j.id,j.ends]));music.setScene(ui.page,state.furnace.jobs);}
let lastBeat=Date.now(),ticks=0;
setInterval(()=>{const now=Date.now();if(serverAccess?.blocked){serverAccess.reconcile();lastBeat=now;return;}furnaceAudio(now);updateFurnaceInput();document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=unified.status);document.querySelectorAll('[data-world-countdown]').forEach(el=>{const seconds=Math.max(0,Math.ceil((Number(el.dataset.worldCountdown)-now-(online.clockOffset||0))/1000));el.textContent=Math.floor(seconds/60)+'m '+seconds%60+'s';});document.querySelectorAll('[data-industry-time],[data-trade-timer]').forEach(el=>{const end=Number(el.dataset.industryTime||el.dataset.tradeTimer);if(end)el.textContent=Math.max(0,Math.ceil((end-now-(online.clockOffset||0))/1000))+'s remaining';});if(!online.active&&!document.hidden)state.stats.playtime+=Math.min(2,(now-lastBeat)/1000);lastBeat=now;ticks++;const previous=state.market.quote,changed=!online.active&&!unified.locked&&!ui.forgePending&&E.background(state,now,ui.industryWorld);if(changed){save();if(!attempt&&['market','smelting','dashboard','inventory','industry'].includes(ui.page)&&!document.activeElement?.matches('input,select'))render();if(previous<state.market.alert&&state.market.quote>=state.market.alert&&state.market.upgrades.includes('alerts'))toast('Price alert: copper reached $'+(state.market.quote/10000).toFixed(4)+'/g.');}else if(ticks%30===0)save();$$('[data-countdown]').forEach(el=>el.textContent=Math.max(0,Math.ceil((state.market.next-now-(state.market.global?(online.clockOffset||0):0))/1000))+'s');$$('[data-refresh-cooldown]').forEach(el=>el.textContent=Math.max(0,Math.ceil((state.market.refreshAt-now)/1000))+'s cooldown');for(const job of state.furnace.jobs){const timer=$(`[data-job-time="${job.id}"]`),bar=$(`[data-job-progress="${job.id}"]`),button=$(`[data-action="furnace-collect"][data-id="${job.id}"]`);if(timer)timer.textContent=job.ends<=now?'Ready to collect':Math.ceil((job.ends-now)/1000)+'s remaining';if(bar)bar.style.width=Math.min(100,(now-job.started)/(job.ends-job.started)*100)+'%';if(button&&job.ends<=now){button.disabled=false;button.textContent='Collect ingots';}}},1000);
const industry=connectIndustry({state:()=>state,ui,online,applyCloud,save,render,toast,modal,close,checkAchievements:E.checkAchievements,world:()=>trade.world(),startAttempt:a=>{attempt=a;briefing();}});
const trade=connectTrade({state:()=>state,ui,online,unified,applyCloud,save,render,toast,modal,close});
if(!serverAccess?.blocked){E.background(state);E.checkAchievements(state);save();}const initialHash=location.hash.slice(1);if(NAV.some(n=>n[0]===initialHash))ui.page=initialHash;render();setTimeout(resumeSavedAttempt,0);requestAnimationFrame(frame);

function applyCloud(data){E.migrateAttempt(data.attempt);if(data.slot&&data.slot!==online.slot)throw Error('Save slot mismatch. Refresh your selected workshop.');online.classification=data.classification||online.classification;if(data.admin)online.admin=data.admin;if(!online.active||online.session?.user.id!==online.activeUserId)throw Error('Your sign-in changed. The local workshop is preserved.');state=E.expansionDefaults(data.state);const tutorialCopy=localStorage.getItem(debugTutorialKey());if(tutorialCopy){try{const meta=E.decode(tutorialCopy);mergeTutorials(state,meta);if(typeof meta.settings?.firstTimeTutorials==='boolean')state.settings.firstTimeTutorials=meta.settings.firstTimeTutorials;}catch{/* Keep malformed metadata for support without replacing the workshop. */}}state.market.global=true;state.goldMarket.history=online.goldMarket?.history||[];if(online.goldMarket)Object.assign(state.goldMarket,online.goldMarket);state.market.history=online.market?.history||[];if(online.market&&online.market.next>=state.market.next)Object.assign(state.market,online.market);online.revision=data.revision;online.attempt=data.attempt;online.lastSync=Date.now();}
async function enterOnline(){if(online.active)return returnLocal();if(!online.username)await online.profile();await unified.connect();if(unified.plan&&!attempt)modal(saveComparison(unified.plan),'result-modal unified-modal');else if(unified.conflict&&!attempt)modal(conflictView(),'result-modal');render();}
function resumeSavedAttempt(){if(serverAccess?.blocked)return;if(online.active||attempt||!state.unifiedAttempt)return;try{const saved=restoreAttempt(state.unifiedAttempt);attempt=saved.attempt;if(attempt.status==='retry'){modal('<div class="result-screen"><h2 id="modal-title">Trial checkpoint restored.</h2><p>Your completed stages and retry budget are preserved.</p>'+primary('retry-trial-stage','Repeat this trial stage')+backButton()+'</div>','result-modal');return;}attempt.status='briefing';if(saved.game){launch(saved.game).then(()=>setPaused(true));}else briefing();}catch(error){toast(error.message);}}
function returnLocal(){debugLoaded=false;online.active=false;online.slot='main';state=clone(unified.doc.state);state.unifiedRuntime={serverTrade:!!unified.doc.ownerId};attempt=null;game=null;render();setTimeout(resumeSavedAttempt,0);}
online.onSignOut=()=>{if(debugLoaded)returnLocal();unified.disconnect();render();};
async function enterDebug(){if(unified.busy||unified.locked)throw Error('Wait for the pending cloud transaction before opening Debug.');if(attempt)throw Error('Finish or leave the challenge before opening Debug.');save();online.slot='debug';const data=await online.load();online.active=true;debugLoaded=true;online.activeUserId=online.session.user.id;applyCloud(data);render();}
async function unifiedAction(name,el){let command=name,p={};if(name==='sell'||name==='sell-custom'){command='trade';p={side:'sell',quality:ui.quality,quote:state.market.quote,amount:(name==='sell'?state.copper[ui.quality]*BigInt(el.dataset.percent)/100n:parseCopper($('#sell-amount').value,$('#sell-unit').value)).toString()};}if(name==='gold-buy'||name==='gold-sell'){command='trade';p={asset:'gold',side:name==='gold-buy'?'buy':'sell',quote:state.goldMarket.quote,amount:parseCopper($('#gold-trade-amount').value,'mg').toString()};}await unified.economic(command,p);render();toast('Worldwide transaction settled once and saved locally.');}
async function verifyOutcome(finished){unsavedOutcome=finished;
 verifying=true;modal('<div class="result-screen"><h2 id="modal-title">Saving your recovery…</h2><p>Your challenge is being checked by the online workshop.</p></div>','result-modal');
 try{
  if(checkpointPending)await checkpointPending;
  const failed=finished.status==='failed';const data=await online.command(failed?'fail':'stage',failed?{}:{attempt:attempt.id,index:attempt.index,events:recording});applyCloud(data);attempt=data.attempt;verifying=false;
  if(failed){verifiedFailure=true;game=finished;checkOutcome();verifiedFailure=false;}
  else if(attempt.status==='complete')complete(data.result);
  else modal(challengeHeader()+'<div class="challenge-intro"><div class="challenge-icon success-icon">'+icon('check')+'</div><h2 id="modal-title">One step closer.</h2><p>Stage '+attempt.index+' verified and saved. Every remaining challenge must be completed.</p>'+primary('next-stage','Continue to stage '+(attempt.index+1))+'</div>','game-modal');
 }catch(error){verifying=false;modal('<div class="result-screen"><h2 id="modal-title">Recovery not yet saved.</h2><p>'+escapeHTML(error.message)+'</p><p>Your local game and original item are preserved. Retry the same save after reconnecting, or refresh your cloud workshop.</p><button class="button primary" data-online="retry-stage">Retry save</button><button class="button secondary" data-online="refresh-stage">Refresh workshop</button></div>','result-modal');}
}
const cloudMutations=new Set(['refund-essence','compression','essence','gold-equipment','gold-research','gold-claim','confirm-ascension','gold-buy','gold-sell','purchase','tool','market-upgrade','sell','sell-custom','market-refresh','set-alert','limit-order','cancel-order','craft','research','roll','equip-aura','equip-and-close','confirm-rebirth','prestige','furnace-queue','furnace-cancel','furnace-start','furnace-collect','furnace-upgrade','sell-ingots','buy-automation','auto-toggle','buy-refining','refine','sell-refined','refining-research','accept-contract','claim-contract','setting','sound','furnace-challenge']);
async function cloudAction(name,el){
 if(!cloudMutations.has(name))return false;
 const p={id:el?.dataset.id};if(el?.dataset.rank)p.rank=Number(el.dataset.rank);let command=name;
 if(name==='sell'||name==='sell-custom'){command='trade';p.side='sell';p.quality=ui.quality;p.quote=state.market.quote;p.amount=(name==='sell'?state.copper[ui.quality]*BigInt(el.dataset.percent)/100n:parseCopper($('#sell-amount').value,$('#sell-unit').value)).toString();}
 if(name==='gold-buy'||name==='gold-sell'){command='trade';p.asset='gold';p.side=name==='gold-buy'?'buy':'sell';p.quote=state.goldMarket.quote;p.amount=$('#gold-trade-amount').value;}
 if(name==='furnace-start'||name==='furnace-queue')p.amount=parseCopper($('#furnace-amount').value,'kg').toString();
 if(name==='set-alert')p.quote=Math.round(Number($('#price-alert').value)*10000);
 if(name==='limit-order'){p.amount=parseCopper($('#sell-amount').value,$('#sell-unit').value).toString();p.quote=Math.round(Number($('#limit-price').value)*10000);p.quality=ui.quality;}
 if(name==='furnace-challenge'){command='begin';p.mode='furnace';p.device=1;}
 const data=await online.command(command,p);applyCloud(data);music.action(name);if(name==='furnace-collect')audioIngots=state.stats.ingots;
 if(name==='furnace-challenge'){attempt=data.attempt;briefing();return true;}
 if(name==='refund-essence'){close();page('ascension');return true;}if(name==='confirm-ascension'){close();page('ascension');return true;}if(name==='confirm-rebirth'||name==='equip-and-close'){close();if(name==='confirm-rebirth')page('rebirth');}
 else render();
 if(name==='roll'){toast('Open Aura Forge to view your saved batch result.');}
 else toast(data.result?.message||(data.result?.proceeds?'Sold for '+money(data.result.proceeds)+'.':'Saved to your online workshop.'));return true;
}
async function onlineAction(name){
 const value=id=>document.getElementById(id)?.value||'';
 try{
 if(!online.client)throw Error(online.error||'The online service is still connecting.');
 switch(name){
 case 'signin':await online.signIn(value('account-email'),value('account-password'));await serverAccess.check();if(!serverAccess.blocked)await enterOnline();break;
 case 'signup':{const ready=await online.signUp(value('signup-email'),value('signup-password'),value('signup-username'));if(ready)await enterOnline();else{render();toast('Check your email to confirm your account, then sign in.');}break;}
 case 'reset':await online.reset(value('account-email'));toast('If that email is registered, a reset link has been sent. Open the newest email on this same device and browser.');break;
 case 'change-password':if(!online.session)throw Error('Sign in or open a fresh reset email first.');online.recovering=true;render();break;
 case 'cancel-password':online.recovering=false;render();break;
 case 'password':await online.password(value('new-password'),value('confirm-password'));render();toast('Password updated.');break;
 case 'online':await enterOnline();break;
 case 'local':returnLocal();break;
 case 'signout':if(online.active)returnLocal();save();await online.signOut();unified.disconnect();render();break;
 case 'boards':await online.pollRankings();render();break;
 case 'buy':{const payload={side:'buy',quality:0,amount:parseCopper(value('buy-copper'),'g').toString(),quote:state.market.quote};if(online.active){applyCloud(await online.command('trade',payload));}else await unified.economic('trade',payload);render();toast('Copper purchased into the same workshop.');break;}
 case 'retry':{if(online.active)applyCloud(await online.retry());else await unified.retry();render();toast('Pending action saved.');break;}
 case 'retry-clock':case 'retry-stage':{const data=await online.retry();applyCloud(data);attempt=data.attempt;if(checkpointRecovery){recording.splice(0,checkpointRecovery);checkpointRecovery=0;if(game){setPaused(false);break;}if(unsavedOutcome){verifyOutcome(unsavedOutcome);break;}}if(attempt?.status==='complete')complete(data.result);else if(attempt?.status==='briefing')briefing();else close();break;}
 case 'refresh-stage':attempt=null;game=null;close();await enterOnline();page('account');break;
 }
 }catch(error){music.cue('incorrect');toast(error.message);}
}
document.addEventListener('click',event=>{const control=event.target.closest('[data-online]');if(control)onlineAction(control.dataset.online);const toggle=event.target.closest('[data-audio-toggle]');if(toggle){const key=toggle.dataset.audioToggle;music.set(key,!music.preference[key]);render();}if(event.target.closest('[data-audio-test]'))music.test();const owner=event.target.closest('[data-owner]');if(owner)music.action(owner.dataset.owner);if(control)music.cue('confirm','interface');});
