let onlinePolling=false,lastCloudPoll=0,lastRevisionPoll=0,marketPollTimer;

async function pollOnline(){ownerPanel?.tick();if(serverAccess?.blocked||document.hidden||onlinePolling||!online.client)return;onlinePolling=true;try{
 if(ui.page==='leaderboards'){await online.pollRankings();render();return;}
 const previous=state.market.quote,market=await online.pollMarket(ui.page==='market',ui.page==='gold');Object.assign(state.market,market);if(online.goldMarket)Object.assign(state.goldMarket,online.goldMarket);paintQuotes(document,state.market.quote,state.goldMarket.quote);const sale=$('[data-sale-preview]');if(sale)sale.textContent=money(E.copperSaleValue(state,state.copper[ui.quality],ui.quality));if(!attempt){const copperChart=$('.market-full .market-chart')||$('.market-preview .market-chart');if(copperChart)copperChart.outerHTML=chart(state,ui.page==='market');const goldChartHost=$('[data-gold-chart]');if(goldChartHost)syncHTML(goldChartHost,goldChart(state.goldMarket));}
 if(Math.abs(market.quote-previous)/Math.max(1,previous)>=.08)music.cue('marketEvent');if(previous<state.market.alert&&market.quote>=state.market.alert&&state.market.upgrades.includes('alerts')){music.cue('alert');toast('Shared price alert: copper reached '+String.fromCharCode(36)+(market.quote/10000).toFixed(4)+'/g.');}
 if(online.active&&!attempt&&!online.busy&&!online.pending&&!ownerPanel?.confirmation&&nextWorkshopDue(state,Date.now()+(online.clockOffset||0),E.bonuses(state))<=Date.now()+(online.clockOffset||0)&&Date.now()-lastCloudPoll>=5000){const data=await online.command('heartbeat');applyCloud(data);lastCloudPoll=Date.now();}
 if(ui.page==='industry')await trade.poll();if(unified.connected&&state.industry.facilities.some(f=>f.queue.length))await trade.world();if(!online.active&&unified.connected&&!unified.busy&&!attempt&&unified.online&&!unified.plan&&!unified.conflict&&Date.now()>=unified.retryAt){const now=Date.now()+(online.clockOffset||0),shippingDue=state.trade.shipments.some(j=>(j.status==='LOADING'?j.departure:j.status==='OUTBOUND'?j.eta:j.returnAt)<=now),limitDue=state.market.limit&&state.market.quote>=state.market.limit.quote;if(shippingDue||limitDue)await unified.economic('heartbeat');}if(online.active&&!attempt&&!online.busy&&!online.pending&&Date.now()-lastRevisionPoll>=60000){lastRevisionPoll=Date.now();const revision=await online.pollRevision();if(revision&&revision.revision!==online.revision){applyCloud(await online.load());if(!document.activeElement?.matches('input,select'))render();}}
 if(online.admin?.owner&&ownerPanel?.open&&!online.busy)await online.adminStatus();ownerPanel?.render();
 if(!attempt&&!document.activeElement?.matches('input,select')&&!ownerPanel?.root.contains(document.activeElement)&&['market','gold','ascension','dashboard','account','leaderboards','smelting','industry'].includes(ui.page))render();
 }catch(error){online.error=error.message;if(online.active&&ui.page==='account'&&!document.activeElement?.matches('input'))render();}finally{onlinePolling=false;clearTimeout(marketPollTimer);const fast=['market','gold','dashboard','industry'].includes(ui.page),delay=ui.page==='leaderboards'?Math.max(1000,(online.rankingsNextPoll||Date.now()+60000)-Date.now()):fast?10000:60000,untilTick=(online.market?.next||0)-Date.now()-(online.clockOffset||0),due=ui.page==='leaderboards'?Infinity:nextWorkshopDue(state,Date.now()+(online.clockOffset||0),E.bonuses(state))-Date.now()-(online.clockOffset||0);marketPollTimer=setTimeout(pollOnline,Math.max(1000,Math.min(delay,fast&&untilTick>0?untilTick+150:delay,Number.isFinite(due)?Math.max(1000,due+200):delay))); }}
ownerPanel=new OwnerAdminPanel({online,state:()=>state,attempt:()=>attempt||online.pending||verifying,pause:()=>{if(game)setPaused(true);},apply:applyCloud,render,enter:enterOnline,poll:pollOnline,enterDebug,leaveDebug:returnLocal,access:serverAccess});
setInterval(()=>ownerPanel.tick(),1000);
online.init().then(async()=>{await serverAccess.check();if(online.authReturn){ui.page='account';history.replaceState(null,'',new URL('./',location.href).pathname+'#account');render();}try{if(!serverAccess.blocked&&!online.authReturn&&!online.recovering&&online.session)await enterOnline();}catch(error){online.error=error.message;}await pollOnline();if(ui.page==='industry')await trade.poll();if(!document.activeElement?.matches('input,select'))render();});
