function gradingResults(p){return '<section class="grading-results" aria-label="Recovery performance"><h3>Final Grade: '+p.grade+' — '+(p.average*100).toFixed(2)+'%</h3><p>Copper grade multiplier '+p.multiplier.toFixed(2)+'×</p><ol>'+p.stages.map(r=>'<li>Stage '+r.stage+': '+(r.score*100).toFixed(2)+'%'+(r.legacy?' · legacy scoring':' · '+r.mistakes+' mistakes · '+r.replays+' replays · '+r.hints+' hints'+(r.penalty?' · −'+(r.penalty*100).toFixed(1)+' points':''))+'</li>').join('')+'</ol>'+(p.grade==='S'&&p.exReasons.length?'<p>EX not achieved: '+p.exReasons.join(' ')+'</p>':'')+'</section>';}
